// Assign stable ids and defaults. Ids derive from track + position and must
// never be reused — a retired question keeps its slot's id out of circulation.
quizTracks.forEach((track) => {
  track.questions.forEach((question, i) => {
    question.id ??= `${track.id}-${String(i + 1).padStart(3, '0')}`;
    question.status ??= 'live';
    question.format ??= 'multiple-choice';
  });
});

export const getQuizTrack = (id: string) => quizTracks.find((track) => track.id === id);

/** Live questions only — retired/draft questions never reach the page. */
export const liveQuestions = (track: QuizTrack) =>
  track.questions.filter((question) => question.status === 'live');
